import { onUpdated, reactive } from 'vue'
import { useResizeObserver } from '@vueuse/core'
import { useNamespace } from '@element-plus/hooks'

import type { Ref } from 'vue'

export const useSelectionTooltip = (
  selectionRef: Ref<HTMLElement | undefined>,
  collapseItemRef: Ref<HTMLElement | undefined>,
  multiple: Ref<boolean>,
  hasModelValue: Ref<boolean>
) => {
  const ns = useNamespace('select')
  const tooltip = reactive({
    visible: false,
    content: '',
    reference: undefined as HTMLElement | undefined,
  })
  let hoveredTarget: HTMLElement | undefined

  const hide = () => {
    hoveredTarget = undefined
    tooltip.visible = false
  }

  const update = () => {
    const selection = selectionRef.value
    if (
      !hasModelValue.value ||
      !selection ||
      !hoveredTarget ||
      !selection.contains(hoveredTarget)
    ) {
      hide()
      return
    }

    let item: HTMLElement | null = null
    if (multiple.value) {
      item = hoveredTarget
      while (item !== selection && item.parentElement !== selection) {
        item = item.parentElement!
      }
      if (
        item === selection ||
        item === collapseItemRef.value ||
        item.classList.contains(ns.e('input-wrapper'))
      ) {
        tooltip.visible = false
        return
      }
    } else {
      item = selection.querySelector(`.${ns.e('placeholder')}`)
    }

    if (!item) {
      tooltip.visible = false
      return
    }

    // Custom labels may truncate a nested element rather than the item itself.
    const overflowing = [item, ...item.querySelectorAll<HTMLElement>('*')].some(
      (element) => {
        const style = getComputedStyle(element)
        return (
          (element.clientWidth > 0 &&
            element.scrollWidth > element.clientWidth &&
            style.overflowX !== 'visible') ||
          (element.clientHeight > 0 &&
            element.scrollHeight > element.clientHeight &&
            style.overflowY !== 'visible')
        )
      }
    )
    const itemRect = item.getBoundingClientRect()
    const selectionRect = selection.getBoundingClientRect()
    const selectionStyle = getComputedStyle(selection)
    const clipped =
      (selectionStyle.overflowX !== 'visible' &&
        (itemRect.left < selectionRect.left - 1 ||
          itemRect.right > selectionRect.right + 1)) ||
      (selectionStyle.overflowY !== 'visible' &&
        (itemRect.top < selectionRect.top - 1 ||
          itemRect.bottom > selectionRect.bottom + 1))

    tooltip.content = item.textContent?.trim() ?? ''
    tooltip.reference = item
    tooltip.visible = !!tooltip.content && (overflowing || clipped)
  }

  const handleMouseMove = (event: MouseEvent) => {
    hoveredTarget = event.target as HTMLElement
    update()
  }

  useResizeObserver(selectionRef, update)
  onUpdated(update)

  return { tooltip, handleMouseMove, hide }
}
